<?php
$id=(int)($_GET['id']??0);$stmt=db()->prepare("SELECT i.*,p.patient_id,p.patient_code,p.full_name patient_name,p.phone,p.email,a.appointment_number FROM invoices i JOIN patients p ON p.patient_id=i.patient_id LEFT JOIN appointments a ON a.appointment_id=i.appointment_id WHERE i.invoice_id=?");$stmt->execute([$id]);$invoice=$stmt->fetch();if(!$invoice||!can_view_patient((int)$invoice['patient_id'])){http_response_code(403);die('Invoice not found or access denied.');}$stmt=db()->prepare('SELECT * FROM invoice_items WHERE invoice_id=? ORDER BY invoice_item_id');$stmt->execute([$id]);$items=$stmt->fetchAll();$stmt=db()->prepare('SELECT * FROM payments WHERE invoice_id=? ORDER BY payment_date');$stmt->execute([$id]);$payments=$stmt->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($invoice['invoice_number'])?></title><style>body{font-family:Arial;color:#172033;background:#eef2f7;margin:0}.sheet{max-width:850px;margin:24px auto;background:#fff;padding:38px;min-height:900px;box-shadow:0 10px 35px #0002}.head{display:flex;justify-content:space-between;border-bottom:3px solid #2563eb;padding-bottom:18px}.logo{font-size:27px;font-weight:800;color:#2563eb}.muted{color:#667085;font-size:13px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:15px;padding:20px 0}.label{font-size:11px;text-transform:uppercase;color:#667085}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #e5e7eb;text-align:left}th{background:#f8fafc;font-size:12px}.summary{width:330px;margin:22px 0 0 auto}.line{display:flex;justify-content:space-between;padding:6px}.total{font-size:20px;border-top:2px solid #172033;margin-top:6px;padding-top:10px}.actions{max-width:850px;margin:18px auto;text-align:right}.btn{padding:10px 15px;background:#2563eb;color:#fff;border:0;border-radius:8px}.footer{margin-top:60px;border-top:1px solid #ddd;padding-top:15px;color:#667085;font-size:12px}@media print{body{background:#fff}.sheet{box-shadow:none;margin:0;max-width:none}.actions{display:none}}</style></head><body><div class="actions"><button class="btn" onclick="window.print()">Print invoice</button></div><main class="sheet"><div class="head"><div><div class="logo">✚ <?=e(setting('hospital_name','MediFlow Hospital'))?></div><div class="muted"><?=e(setting('hospital_address',''))?> · <?=e(setting('hospital_phone',''))?></div></div><div style="text-align:right"><h2 style="margin:0">INVOICE</h2><strong><?=e($invoice['invoice_number'])?></strong><div class="muted"><?=format_date($invoice['created_at'],'d M Y, h:i A')?></div></div></div><div class="meta"><div><div class="label">Bill to</div><strong><?=e($invoice['patient_name'])?></strong><div class="muted"><?=e($invoice['patient_code'])?> · <?=e($invoice['phone']??'')?><br><?=e($invoice['email']??'')?></div></div><div><div class="label">Reference</div><strong><?=e($invoice['appointment_number']??'Manual invoice')?></strong><div class="muted">Payment status: <?=e($invoice['payment_status'])?></div></div></div><table><thead><tr><th>Description</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['description'])?><div class="muted"><?=e($item['item_type'])?></div></td><td><?=e($item['quantity'])?></td><td><?=money($item['unit_price'])?></td><td><?=money($item['line_total'])?></td></tr><?php endforeach;?></tbody></table><div class="summary"><div class="line"><span>Subtotal</span><strong><?=money($invoice['subtotal'])?></strong></div><div class="line"><span>Discount</span><strong>- <?=money($invoice['discount_amount'])?></strong></div><div class="line"><span>Tax</span><strong><?=money($invoice['tax_amount'])?></strong></div><div class="line total"><span>Total</span><strong><?=money($invoice['total_amount'])?></strong></div><div class="line"><span>Paid</span><strong><?=money($invoice['paid_amount'])?></strong></div><div class="line"><span>Due</span><strong><?=money($invoice['due_amount'])?></strong></div></div><?php if($payments):?><h3>Payment history</h3><table><thead><tr><th>Payment</th><th>Method</th><th>Date</th><th>Amount</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=e($p['payment_number'])?></td><td><?=e($p['payment_method'])?></td><td><?=format_date($p['payment_date'],'d M Y, h:i A')?></td><td><?=money($p['amount'])?></td></tr><?php endforeach;?></tbody></table><?php endif;?><div class="footer">Generated by MediFlow. This is a system-generated invoice and payment record.</div></main></body></html>
